import { test, expect } from '@playwright/test';

test.describe('Notification Auto-Dismissal', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/notifications');
  });

  test('should auto-dismiss notifications after 5 seconds', async ({ page }) => {
    // Verify notification container is visible
    const notificationContainer = page.getByRole('region', { name: /notifications/i });
    await expect(notificationContainer).toBeVisible();

    // Verify notification list is visible
    const notificationList = page.getByRole('list', { name: /notifications/i });
    await expect(notificationList).toBeVisible();

    // Verify notification item exists
    const notificationItem = page.getByRole('listitem', { name: /new message/i });
    await expect(notificationItem).toBeVisible();

    // Verify notification has a dismiss button
    const dismissButton = page.getByRole('button', { name: /dismiss/i });
    await expect(dismissButton).toBeVisible();

    // Verify notification is visible with initial styling
    const notificationContent = page.getByText(/new message/i);
    await expect(notificationContent).toBeVisible();

    // Wait for auto-dismissal timeout
    await page.waitForTimeout(5100);

    // Verify notification has been dismissed
    await expect(notificationItem).not.toBeVisible();

    // Verify notification container is still visible
    await expect(notificationContainer).toBeVisible();

    // Verify notification list is empty
    const emptyState = page.getByText(/no notifications/i);
    await expect(emptyState).toBeVisible();
  });

  test('should not auto-dismiss notification if user interacts with it', async ({ page }) => {
    // Verify notification container is visible
    const notificationContainer = page.getByRole('region', { name: /notifications/i });
    await expect(notificationContainer).toBeVisible();

    // Verify notification item exists
    const notificationItem = page.getByRole('listitem', { name: /new message/i });
    await expect(notificationItem).toBeVisible();

    // Verify notification is visible with initial styling
    const notificationContent = page.getByText(/new message/i);
    await expect(notificationContent).toBeVisible();

    // Interact with notification by clicking on it
    await notificationItem.click();

    // Verify notification remains visible after interaction
    await expect(notificationItem).toBeVisible();

    // Verify notification content is still visible
    await expect(notificationContent).toBeVisible();

    // Wait for auto-dismissal timeout
    await page.waitForTimeout(5100);

    // Verify notification still exists after timeout
    await expect(notificationItem).toBeVisible();

    // Verify notification has a 'keep' button
    const keepButton = page.getByRole('button', { name: /keep/i });
    await expect(keepButton).toBeVisible();

    // Click keep button to confirm it stays
    await keepButton.click();
    await expect(notificationItem).toBeVisible();
  });
});
